import { DatabaseSync } from "node:sqlite";

export interface SeedTask {
  title: string;
  created_at: string;
}

/**
 * Inserts tasks straight into a database file whose server is already running (so the `tasks`
 * table exists). The public API stamps `created_at` itself, so this is the only way to put
 * tasks at exactly the same instant, or out of order, on purpose. Rows get ids in array order.
 */
export function seedTasks(dbPath: string, tasks: SeedTask[]): void {
  const db = new DatabaseSync(dbPath);
  try {
    db.exec("PRAGMA busy_timeout = 5000");
    const insert = db.prepare(
      "INSERT INTO tasks (title, created_at, updated_at) VALUES (?, ?, ?)",
    );
    db.exec("BEGIN");
    for (const task of tasks) insert.run(task.title, task.created_at, task.created_at);
    db.exec("COMMIT");
  } finally {
    db.close();
  }
}
