cat > tests/newest-first.test.ts <<'EOF'
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { runInNewContext } from "node:vm";
import { after, before, describe, it } from "node:test";
import { seedTasks } from "./helpers/seed.ts";
import { newDbPath, ROOT, startServer, type Running } from "./helpers/server.ts";

interface Task {
  id: number;
  title: string;
  created_at: string;
  updated_at: string;
  completed_at: string | null;
}

async function createTask(server: Running, title: string): Promise<Task> {
  const response = await fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title }),
  });
  assert.equal(response.status, 201);
  return ((await response.json()) as { task: Task }).task;
}

async function listTitles(server: Running): Promise<string[]> {
  const response = await fetch(`${server.baseUrl}/api/tasks`);
  assert.equal(response.status, 200);
  const { tasks } = (await response.json()) as { tasks: Task[] };
  return tasks.map((task) => task.title);
}

describe("SL-008 open tasks newest first, with an empty state", () => {
  describe("AC-1: open tasks added in the order A, B, C", () => {
    let server: Running;

    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-1: GET /api/tasks lists C, B, A", async () => {
      for (const title of ["A", "B", "C"]) await createTask(server, title);
      assert.deepEqual(await listTitles(server), ["C", "B", "A"]);
    });

    it("AC-1: a task added later goes to the top of the list", async () => {
      await createTask(server, "D");
      assert.deepEqual(await listTitles(server), ["D", "C", "B", "A"]);
    });
  });

  describe("AC-1: creation time decides first", () => {
    const dbPath = newDbPath();
    let server: Running;

    before(async () => {
      server = await startServer(dbPath);
      // Saved first but created last, and the other way round: id order and time order disagree.
      seedTasks(dbPath, [
        { title: "created last, saved first", created_at: "2026-03-01T10:00:03.000Z" },
        { title: "created first, saved last", created_at: "2026-03-01T10:00:01.000Z" },
        { title: "created second, saved second", created_at: "2026-03-01T10:00:02.000Z" },
      ]);
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-1: the later created_at is listed first, whatever the id", async () => {
      assert.deepEqual(await listTitles(server), [
        "created last, saved first",
        "created second, saved second",
        "created first, saved last",
      ]);
    });
  });

  describe("AC-2: tasks created within the same instant", () => {
    const dbPath = newDbPath();
    let server: Running;

    before(async () => {
      server = await startServer(dbPath);
      const sameInstant = "2026-03-01T10:00:00.000Z";
      seedTasks(
        dbPath,
        ["first", "second", "third", "fourth", "fifth"].map((title) => ({
          title,
          created_at: sameInstant,
        })),
      );
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-2: the one saved last is listed first", async () => {
      assert.deepEqual(await listTitles(server), ["fifth", "fourth", "third", "second", "first"]);
    });

    it("AC-2: the order is the same on every request", async () => {
      const expected = await listTitles(server);
      for (let request = 0; request < 10; request++) {
        assert.deepEqual(await listTitles(server), expected);
      }
    });

    it("AC-2: tasks posted back to back come out in exact reverse order", async () => {
      const titles = Array.from({ length: 30 }, (_, index) => `burst ${index}`);
      for (const title of titles) await createTask(server, title);

      const listed = (await listTitles(server)).filter((title) => title.startsWith("burst "));
      assert.deepEqual(listed, [...titles].reverse());
    });
  });

  describe("AC-3: an empty list", () => {
    let server: Running;
    let html: string;
    let script: string;

    before(async () => {
      server = await startServer();
      html = await (await fetch(`${server.baseUrl}/`)).text();
      script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-3: GET /api/tasks answers 200 with an empty list, not an error", async () => {
      const response = await fetch(`${server.baseUrl}/api/tasks`);
      assert.equal(response.status, 200);
      assert.deepEqual(await response.json(), { tasks: [] });
    });

    it("AC-3: the page has an empty-state element, outside the task list", () => {
      assert.match(html, /<[a-z0-9]+(?=[^>]*\bid=["']empty-state["'])[^>]*>/i);
      assert.doesNotMatch(
        html,
        /<ul[^>]*id=["']task-list["'][^>]*>(?:(?!<\/ul>)[\s\S])*id=["']empty-state["']/i,
        "the empty state must not be an item inside the ul",
      );
    });

    // No browser (non-goal), so the real public/app.js runs against a minimal fake page.
    // "Visible" means the element's `hidden` property is false.
    function runPage(tasks: Pick<Task, "title">[]) {
      const initiallyHidden = (id: string) =>
        new RegExp(`<[a-z0-9]+(?=[^>]*\\bid=["']${id}["'])(?=[^>]*\\shidden\\b)[^>]*>`, "i").test(
          html,
        );
      const elements = new Map<string, any>();
      const makeElement = (hidden = false): any => ({
        hidden,
        textContent: "",
        value: "",
        children: [] as any[],
        addEventListener() {},
        replaceChildren(...nodes: any[]) {
          this.children = nodes;
        },
        append(...nodes: any[]) {
          this.children.push(...nodes);
        },
      });
      const document = {
        getElementById(id: string) {
          if (!elements.has(id)) elements.set(id, makeElement(initiallyHidden(id)));
          return elements.get(id);
        },
        createElement: () => makeElement(),
      };
      const errors: unknown[] = [];
      const fetched: string[] = [];
      const fetchStub = async (url: string) => {
        fetched.push(String(url));
        return { ok: true, status: 200, json: async () => ({ tasks }) };
      };
      runInNewContext(script, {
        document,
        fetch: fetchStub,
        console: { ...console, error: (...args: unknown[]) => errors.push(args) },
      });
      const settled = (async () => {
        for (let turn = 0; turn < 10; turn++) await new Promise((r) => setImmediate(r));
      })();
      return { document, errors, fetched, settled };
    }

    it("AC-3: with no tasks the page shows the empty state and no error", async () => {
      const page = runPage([]);
      await page.settled;

      assert.ok(page.fetched.some((url) => url.includes("/api/tasks")));
      assert.equal(page.document.getElementById("task-list").children.length, 0);
      assert.equal(page.document.getElementById("empty-state").hidden, false);
      assert.deepEqual(page.errors, []);
    });

    it("AC-3: with tasks the page lists them in API order and hides the empty state", async () => {
      const page = runPage([{ title: "C" }, { title: "B" }, { title: "A" }]);
      await page.settled;

      const shown = page.document.getElementById("task-list").children.map((li: any) => li.textContent);
      assert.deepEqual(shown, ["C", "B", "A"]);
      assert.equal(page.document.getElementById("empty-state").hidden, true);
    });
  });

  describe("AC-4: about 1000 stored tasks", () => {
    const dbPath = newDbPath();
    let server: Running;

    before(async () => {
      server = await startServer(dbPath);
      const start = Date.parse("2026-03-01T00:00:00.000Z");
      seedTasks(
        dbPath,
        Array.from({ length: 1000 }, (_, index) => ({
          title: `Task number ${String(index).padStart(4, "0")}: something to do soon`,
          created_at: new Date(start + index * 1000).toISOString(),
        })),
      );
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-4: 20 sequential GET /api/tasks have p95 under 100 ms and a body under 400000 bytes", async () => {
      const durations: number[] = [];
      let largestBody = 0;
      for (let request = 0; request < 20; request++) {
        const begun = performance.now();
        const response = await fetch(`${server.baseUrl}/api/tasks`);
        const body = await response.arrayBuffer();
        durations.push(performance.now() - begun);
        assert.equal(response.status, 200);
        largestBody = Math.max(largestBody, body.byteLength);
      }

      durations.sort((a, b) => a - b);
      const p95 = durations[Math.ceil(0.95 * durations.length) - 1];
      assert.ok(p95 < 100, `p95 was ${p95.toFixed(1)} ms`);
      assert.ok(largestBody < 400_000, `body was ${largestBody} bytes`);
    });

    it("AC-4: with 1000 tasks the newest is still listed first", async () => {
      const titles = await listTitles(server);
      assert.equal(titles.length, 1000);
      assert.equal(titles[0], "Task number 0999: something to do soon");
      assert.equal(titles[999], "Task number 0000: something to do soon");
    });
  });
});
